CREATE OR REPLACE FUNCTION public.biz_goal_decide(_version_id uuid,_revision int,_approve boolean,_comment text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v public.biz_goal_versions; g public.biz_annual_goals; final_ boolean; managed_ boolean;
BEGIN
 SELECT * INTO v FROM public.biz_goal_versions WHERE id=_version_id FOR UPDATE; SELECT * INTO g FROM public.biz_annual_goals WHERE id=v.goal_id FOR UPDATE;
 managed_:=EXISTS(SELECT 1 FROM public.biz_approval_runs WHERE version_id=v.id AND status='pending');
 IF NOT managed_ AND NOT public.biz_goal_can_review(g.user_id,g.department_id) THEN RAISE EXCEPTION 'Không có quyền duyệt mục tiêu này hoặc không được tự duyệt.'; END IF;
 IF v.status<>'pending' OR v.revision<>_revision THEN RAISE EXCEPTION 'Mục tiêu không còn chờ duyệt. Hãy tải lại.'; END IF;
 IF NOT _approve AND btrim(coalesce(_comment,''))='' THEN RAISE EXCEPTION 'Cần nhận xét yêu cầu chỉnh sửa.'; END IF;
 final_:=public.biz_approval_step(v.id,_approve,_comment);
 UPDATE public.biz_goal_versions SET status=CASE WHEN final_ THEN 'approved' WHEN NOT _approve THEN 'changes' ELSE 'pending' END,review_comment=nullif(btrim(_comment),''),approved_at=CASE WHEN final_ THEN now() END,approved_by=CASE WHEN final_ THEN auth.uid() END,revision=revision+1,updated_at=now() WHERE id=v.id;
 IF final_ THEN UPDATE public.biz_annual_goals SET official_version_id=v.id WHERE id=g.id; END IF;
 INSERT INTO public.biz_goal_events(goal_id,version_id,actor_id,action,comment,payload) VALUES(g.id,v.id,auth.uid(),CASE WHEN final_ THEN 'approved' WHEN NOT _approve THEN 'returned' ELSE 'step_approved' END,_comment,jsonb_build_object('version',v.version));
END $$;
CREATE OR REPLACE FUNCTION public.biz_document_decide(_id uuid,_revision integer,_approve boolean,_comment text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v public.biz_document_versions; d public.biz_documents; final_ boolean; managed_ boolean;
BEGIN
 SELECT * INTO v FROM public.biz_document_versions WHERE id=_id FOR UPDATE; SELECT * INTO d FROM public.biz_documents WHERE id=v.document_id FOR UPDATE;
 managed_:=EXISTS(SELECT 1 FROM public.biz_approval_runs WHERE version_id=v.id AND status='pending');
 IF NOT managed_ AND NOT public.biz_doc_access(d.user_id,d.department_id,d.kind,true) THEN RAISE EXCEPTION 'Không có quyền duyệt hoặc không được tự duyệt.'; END IF;
 IF d.kind='plan' AND _approve THEN RAISE EXCEPTION 'Kế hoạch không cần phê duyệt. Chỉ có thể yêu cầu chỉnh sửa.'; END IF;
 IF v.status NOT IN ('pending','resubmitted') OR (d.kind<>'plan' AND v.status<>'pending') OR v.revision<>_revision THEN RAISE EXCEPTION 'Tài liệu đã thay đổi trạng thái. Hãy tải lại.'; END IF;
 IF NOT _approve AND btrim(coalesce(_comment,''))='' THEN RAISE EXCEPTION 'Cần nhập nội dung yêu cầu chỉnh sửa.'; END IF;
 final_:=CASE WHEN d.kind='plan' THEN false ELSE public.biz_approval_step(v.id,_approve,_comment) END;
 UPDATE public.biz_document_versions SET status=CASE WHEN final_ THEN 'approved' WHEN NOT _approve THEN 'changes' ELSE 'pending' END,review_comment=nullif(btrim(_comment),''),approved_at=CASE WHEN final_ THEN now() END,approved_by=CASE WHEN final_ THEN auth.uid() END,revision=revision+1 WHERE id=v.id;
 IF final_ THEN UPDATE public.biz_documents SET official_version_id=v.id WHERE id=d.id; END IF;
 INSERT INTO public.biz_document_events(document_id,version_id,actor_id,action,payload) VALUES(d.id,v.id,auth.uid(),CASE WHEN final_ THEN 'approved' WHEN NOT _approve THEN 'returned' ELSE 'step_approved' END,jsonb_build_object('comment',_comment,'items',v.items,'target_version_id',v.target_version_id));
END $$;
CREATE OR REPLACE FUNCTION public.biz_document_notify() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE d public.biz_documents;recipient uuid;label text;
BEGIN
 SELECT * INTO d FROM public.biz_documents WHERE id=NEW.document_id;
 IF EXISTS(SELECT 1 FROM public.biz_approval_runs WHERE version_id=NEW.version_id) THEN RETURN NEW; END IF;
 IF NEW.action NOT IN ('submitted','approved','returned') THEN RETURN NEW;END IF;
 label:=CASE d.kind WHEN 'plan' THEN 'Kế hoạch' ELSE 'Báo cáo' END;
 FOR recipient IN SELECT p.id FROM public.profiles p WHERE p.status='Đang hoạt động' AND CASE WHEN NEW.action='submitted' THEN p.id<>d.user_id AND (private.sig_can(p.id,'biz.'||d.kind||'_approve') OR (d.kind='plan' AND private.sig_can(p.id,'biz.plan_request_revision'))) AND public.biz_scope_ok(p.id,d.user_id,d.department_id) ELSE p.id=d.user_id AND (private.sig_can(p.id,'biz.'||d.kind||'_submit') OR private.sig_can(p.id,'biz.view_own')) END LOOP
 INSERT INTO public.notifications(recipient_id,kind,dedup_key,payload,zalo_status,push_status) VALUES(recipient,'biz_'||NEW.action,'biz:'||NEW.id||':'||recipient,jsonb_build_object('message',label||CASE WHEN d.kind='plan' AND NEW.action='submitted' THEN CASE WHEN (NEW.payload->>'resubmitted')::boolean THEN ' đã được nộp lại.' ELSE ' đã được nộp.' END WHEN d.kind='plan' AND NEW.action='returned' THEN ' cần chỉnh sửa: '||left(coalesce(NEW.payload->>'comment',''),200) WHEN NEW.action='submitted' THEN ' đang chờ duyệt.' WHEN NEW.action='approved' THEN ' đã được duyệt.' ELSE ' cần chỉnh sửa.' END,'document_id',d.id,'kind',d.kind,'period_kind',d.period_kind,'year',d.year,'period',d.period,'user_id',d.user_id),'ineligible','none') ON CONFLICT(dedup_key) DO NOTHING;
 END LOOP;RETURN NEW;
END $$;
CREATE OR REPLACE FUNCTION public.biz_goal_can_review(_user_id uuid,_department_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _user_id<>auth.uid() AND private.sig_can(auth.uid(),'biz.goal_approve') AND (EXISTS(SELECT 1 FROM public.biz_goal_versions v JOIN public.biz_annual_goals g ON g.id=v.goal_id WHERE g.user_id=_user_id AND g.department_id=_department_id AND public.biz_run_assigned(v.id,true)) OR public.biz_scope_ok(auth.uid(),_user_id,_department_id)) $$;
CREATE OR REPLACE FUNCTION public.biz_goal_can_read(_goal_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.biz_annual_goals g WHERE g.id=_goal_id AND (public.is_super_admin(auth.uid()) OR (g.user_id=auth.uid() AND (private.sig_can(auth.uid(),'biz.view_own') OR private.sig_can(auth.uid(),'biz.goal_submit'))) OR private.sig_can(auth.uid(),'biz.view_all') OR EXISTS(SELECT 1 FROM public.biz_goal_versions v WHERE v.goal_id=g.id AND public.biz_run_assigned(v.id)) OR ((private.sig_can(auth.uid(),'biz.view_dept') OR private.sig_can(auth.uid(),'biz.goal_approve')) AND public.biz_scope_ok(auth.uid(),g.user_id,g.department_id)))) $$;
CREATE OR REPLACE FUNCTION public.biz_doc_access(_user uuid,_dept uuid,_kind text,_review boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN _kind NOT IN ('plan','report') THEN false WHEN _review THEN _user<>auth.uid() AND (CASE WHEN _kind='plan' THEN private.sig_can(auth.uid(),'biz.plan_request_revision') OR private.sig_can(auth.uid(),'biz.plan_approve') ELSE private.sig_can(auth.uid(),'biz.report_approve') END) AND (public.biz_scope_ok(auth.uid(),_user,_dept) OR (_kind='report' AND EXISTS(SELECT 1 FROM public.biz_document_versions v JOIN public.biz_documents d ON d.id=v.document_id WHERE d.user_id=_user AND d.department_id=_dept AND d.kind='report' AND public.biz_run_assigned(v.id,true)))) ELSE public.is_super_admin(auth.uid()) OR (_user=auth.uid() AND (private.sig_can(auth.uid(),'biz.view_own') OR private.sig_can(auth.uid(),'biz.'||_kind||'_submit'))) OR private.sig_can(auth.uid(),'biz.view_all') OR (_kind='report' AND EXISTS(SELECT 1 FROM public.biz_document_versions v JOIN public.biz_documents d ON d.id=v.document_id WHERE d.user_id=_user AND d.department_id=_dept AND d.kind='report' AND public.biz_run_assigned(v.id))) OR ((private.sig_can(auth.uid(),'biz.view_dept') OR private.sig_can(auth.uid(),'biz.'||_kind||'_approve') OR (_kind='plan' AND private.sig_can(auth.uid(),'biz.plan_request_revision'))) AND public.biz_scope_ok(auth.uid(),_user,_dept)) END $$;
CREATE OR REPLACE FUNCTION public.biz_department_access(_department_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_super_admin(auth.uid()) OR public.biz_org_can_manage() OR private.sig_can(auth.uid(),'biz.workflow_manage') OR private.sig_can(auth.uid(),'biz.view_all') OR private.sig_can(auth.uid(),'biz.dept_manage') OR private.sig_can(auth.uid(),'biz.kr_manage') OR EXISTS(SELECT 1 FROM public.biz_department_members m WHERE m.department_id=_department_id AND ((m.user_id=auth.uid() AND m.ended_at IS NULL AND (private.sig_can(auth.uid(),'biz.view_own') OR private.sig_can(auth.uid(),'biz.goal_submit'))) OR ((private.sig_can(auth.uid(),'biz.view_dept') OR private.sig_can(auth.uid(),'biz.goal_approve')) AND public.biz_scope_ok(auth.uid(),m.user_id,_department_id)))) $$;
CREATE OR REPLACE FUNCTION public.biz_member_access(_user_id uuid,_department_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.biz_org_can_manage() OR private.sig_can(auth.uid(),'biz.dept_manage') OR private.sig_can(auth.uid(),'biz.view_all') OR (_user_id=auth.uid() AND (private.sig_can(auth.uid(),'biz.view_own') OR private.sig_can(auth.uid(),'biz.goal_submit'))) OR ((private.sig_can(auth.uid(),'biz.view_dept') OR private.sig_can(auth.uid(),'biz.goal_approve')) AND public.biz_scope_ok(auth.uid(),_user_id,_department_id)) $$;